+    #[test]
+    fn incremental_commit_limits_match_full_prefix_checks() {
+        let row = BTreeMap::from([
+            ("null".to_string(), Value::Null),
+            ("number".to_string(), Value::Int(7)),
+            (
+                "nested".to_string(),
+                Value::List(vec![
